export const DEFAULT_DEVICES = {
  android: "google-pixel-9",
  iphone: "apple-iphone-16-pro",
  desktop: "desktop-large",
  tablet: "apple-ipad-pro-11-m4",
  foldable: "samsung-galaxy-z-fold-8",
};

export function getDeviceSpec(deviceType = "android") {
  if (DEVICE_SPECS[deviceType]) {
    return DEVICE_SPECS[deviceType];
  }
  const fallbackId = DEFAULT_DEVICES[deviceType] || "google-pixel-9";
  return DEVICE_SPECS[fallbackId] || DEVICE_SPECS["google-pixel-9"];
}
